import { Clock } from '../kernel/clock';

export interface Schedule {
  hour: number;
  minute: number;
}

export function nextRun(schedule: Schedule, clock: Clock): Date {
  const now = clock.now();
  const next = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate(),
    schedule.hour,
    schedule.minute,
    0,
    0
  );

  if (next.getTime() <= now.getTime()) {
    next.setDate(next.getDate() + 1);
  }

  return next;
}

